<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MethodicalOfficeController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.view')||$r->user()->canDo('methodical.manage'),403);}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.manage'),403);}
public function index(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$stats=['materials'=>DB::table('methodical_materials')->where('academic_period_id',$p->id)->count(),'review'=>DB::table('methodical_materials')->where(['academic_period_id'=>$p->id,'status'=>'review'])->count(),'meetings'=>DB::table('methodical_meetings')->where('academic_period_id',$p->id)->count(),'tasks'=>DB::table('methodical_tasks')->whereNotIn('status',['done','cancelled'])->count(),'development'=>DB::table('teacher_development_records')->where('next_due_on','<=',date('Y-m-d',strtotime('+90 days')))->count(),'observations'=>DB::table('lesson_observations')->where('academic_period_id',$p->id)->count()];return view('methodical.index',compact('stats'));}
public function commissions(Request $r){$this->manage($r);$rows=DB::table('methodical_commissions as c')->leftJoin('teachers as t','t.id','=','c.chair_teacher_id')->select('c.*','t.last_name as chair_name')->orderBy('c.name')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();return view('methodical.commissions',compact('rows','teachers'));}
public function commissionStore(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:500','code'=>'nullable|string|max:100|unique:methodical_commissions,code','chair_teacher_id'=>'nullable|exists:teachers,id','note'=>'nullable|string|max:3000']);DB::table('methodical_commissions')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function materials(Request $r){$this->view($r);$p=$r->attributes->get('academic_period');$rows=DB::table('methodical_materials as m')->leftJoin('teachers as t','t.id','=','m.teacher_id')->leftJoin('methodical_commissions as c','c.id','=','m.methodical_commission_id')->where('m.academic_period_id',$p->id)->select('m.*','t.last_name as teacher_name','c.name as commission_name')->orderByDesc('m.id')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();$commissions=DB::table('methodical_commissions')->where('active',1)->orderBy('name')->get();return view('methodical.materials',compact('rows','teachers','commissions'));}
public function materialStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['teacher_id'=>'nullable|exists:teachers,id','methodical_commission_id'=>'nullable|exists:methodical_commissions,id','type'=>'required|in:work_program,ktp,methodical_guide,assessment_material,open_lesson,other','title'=>'required|string|max:500','version'=>'nullable|string|max:100','valid_from'=>'nullable|date','valid_to'=>'nullable|date|after_or_equal:valid_from','description'=>'nullable|string|max:10000']);DB::table('methodical_materials')->insert($d+['academic_period_id'=>$p->id,'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function review(Request $r,$id){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.review'),403);$d=$r->validate(['decision'=>'required|in:approved,revision,rejected','comment'=>'nullable|string|max:10000']);DB::transaction(function()use($id,$d,$r){DB::table('methodical_reviews')->insert(['methodical_material_id'=>$id,'decision'=>$d['decision'],'comment'=>$d['comment']??null,'reviewed_at'=>now(),'reviewed_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('methodical_materials')->where('id',$id)->update(['status'=>$d['decision'],'updated_at'=>now()]);});return back();}
}